def nested(h,w,colors):
    a=[[colors[0]]*w for _ in range(h)]
    k=1
    inset=1
    while inset*2<h and inset*2<w:
        col=colors[k]
        for r in range(inset,h-inset):
            for c in range(inset,w-inset):
                if r in (inset,h-1-inset) or c in (inset,w-1-inset):
                    a[r][c]=col
        k=(k+1)%len(colors)
        inset+=2
    return a
